#!/usr/bin/env python3
"""Write out/SUMMARY.md: every answer of SPEC.md in a line or two with its sample and conditions, the most striking
findings per question (with witness ids from out/witness.json), the checks, and the claims verdicts.  Every number is
read from the files in out/; nothing is typed in."""
import csv, json, os

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, '..', 'out')
J = lambda n: json.load(open(os.path.join(OUT, n)))
X = json.load(open(os.path.join(OUT, 'report_extra.json')))   # made by xtables.py
def rd(name):
    return list(csv.DictReader((l for l in open(os.path.join(OUT, name)) if not l.startswith('#')), delimiter='\t'))
P = lambda x, d=1: f'{100 * float(x):.{d}f}%'
F = lambda x, d=2: f'{float(x):.{d}f}'
A = J('a50k_stats.json'); S5 = J('s500_stats.json'); B = J('b_stats.json'); C = J('c_stats.json'); W = J('witness.json')
a1 = {r['what']: r for r in rd('a50k_a1.tsv')}
a1c = {r['length']: r for r in rd('a50k_a1_counts.tsv')}
a2 = rd('a50k_a2.tsv'); a2s = rd('s500_a2.tsv')
a3 = rd('a50k_a3.tsv'); a3s = rd('s500_a3.tsv')
b4 = rd('a50k_b4.tsv'); b4x = rd('b4_one_axis_exact.tsv'); byb = {int(r['bad']): r for r in rd('b5_by_bad.tsv')}
c6 = {r['case']: r for r in rd('c6_by_case.tsv')}; c7 = rd('c7_typical.tsv'); ni = {r['case']: r for r in rd('c6_normal_inverse.tsv')}
claims = rd('claims.tsv'); prior = rd('compare_prior.tsv'); chk = rd('checks_nissy.tsv'); cnt = rd('checks_counts.tsv'); scrchk = rd('checks_scrambles.tsv')
n = A['n']
def wid(q, word):
    for w in W:
        if w['question'] == q and word in w['finding']:
            return f"[{w['id']}]"
    return ''
def a2r(rows, kind, k):
    return next(r for r in rows if r['eo_kind'].startswith(kind) and r['k'] == str(k))
def a3r(rows, eos, axes, k, N):
    return next(r for r in rows if r['eos'] == eos and r['axes'] == axes and r['eo_max'] == str(k) and r['dr_total_max'] == str(N))
def b4r(eos, axes, L):
    return next(r for r in b4 if r['eos'] == eos and r['axes'] == axes and r['length'] == str(L))
L = []
w = L.append
w('# EO → DR and scramble → DR: the numbers\n')
w(f"Generated by `src/summary.py` from the files in `out/`. Scramble-level answers: {n:,} uniformly random states (`out/scrambles.txt`, "
  "`eodrtools mkscr`, seed 2026) and the 500 scrambles of judging-a-dr; EO→DR: exact over the 1,082,565 EO-solved cosets where "
  "marked, else 10,000,000 uniformly random EO-solved states with exact table lookups. Turns are face turns (HTM); canonical "
  "sequences; an EO or a DR solution is counted when it is reached for the first time at its last turn (nissy's `-a` listing). "
  "Normal = after the scramble, inverse = after the inverse scramble, NISS = both sides (length = sum). A route through an EO = "
  "the EO, then turns that keep it, to a DR on one of the two other axes. Definitions in detail: `README.md`. Witnesses [Wn]: "
  "`out/witness.json`, every solution replayed on the sticker model.\n")

# ---------------- checks
w('## Checks (all passed before any number was used)\n')
tot = sum(int(r['positions']) for r in chk); ok = sum(int(r['agree']) for r in chk)
w(f"- Table mappings against nissy 2.0.8: {ok:,} of {tot:,} positions agree, {len(chk)} mappings x 1000 positions (2000 for the any-turn ones): "
  "DR from scratch on each axis (all_dr through a rotation), EO-keeping DR for all six (EO axis, DR axis) pairs, any-turn DR from "
  "EO-solved positions, optimal EO per axis, NISS EO over all axes (`out/checks_nissy.tsv`).")
w(f"- {open(os.path.join(OUT, 'checks_bits.txt')).read().strip()}.")
w('- Counts against nissy on 30 scrambles (`out/checks_counts.tsv`): ' + '; '.join(f"{r['check']} {r['agree']}/{r['scrambles']}" for r in cnt if not r['agree'].startswith('not')) + '.')
w(f"- Known distributions reproduced exactly: the EO-solved part of eo-fb_dr is Cale's 1,082,565 states 1, 2, 17, 134, 1065, 8190, 54694, 267576, 560568, 187204, 3114 (mean {F(c7[0]['mean'], 4)}); "
  f"the any-turn version gives torchlight's {F(c7[1]['mean'], 4)}; one-axis EO mean {B['one_axis_optimal_mean']} (DougCube's 4.609); "
  f"best NISS EO over all axes {B['any_axis_niss']['mean']} on 1,000,000 random states (Joba's exact 3.455); all_dr.hist 1, 4, 50, 592, …, 476 (fixed-axis row below).")
w(f"- Sticker-model replays: every solution in the 50,000-, 500- and superflip tables (NISS DR, an optimal DR with its EO split, the best routes through EOs of ≤4, 5, 6) and every witness.")
fx = a1['fixed axis, all three axes pooled, sampled']
w(f"- Sample against exact: fixed-axis DR length on the sample, mean {fx['mean']} (3 x {n:,} axes), against the exact {a1['fixed axis, exact (all 2,217,093,120 cosets)']['mean']}. " +
  '; '.join(f"{r['measure']}: chi2 {r['chi2']} on {r['df']} df against {'the exact table' if 'one axis' in r['measure'] else 'is-dr-xs-worth-it 6.4 (2,000,000 states)'}" for r in prior) + '.')
bad = [r for r in scrchk if r['scrambles'] == 'nissy' and r['what'] == 'twisted corners']
good = [r for r in scrchk if r['scrambles'] == 'mkscr']
import math as _m
def _p(chi2, df):
    x, k = float(chi2) / 2, int(df) / 2
    s, term, i = 0.0, 1.0 / k, 0
    while term > 1e-15:
        s += term; i += 1; term *= x / (k + i)
    return 1 - _m.exp(-x + k * _m.log(x) - _m.lgamma(k)) * s
nb = json.load(open(os.path.join(OUT, 'nissy50k_stats.json')))['a1']
w(f"- **nissy 2.0.8's `scramble` is not uniform**: its source (src/commands.c, lines 505-508) draws `ep = rand() % FACTORIAL12`, and rand() "
  f"has 2^31 values, about 4.48 times 12!, so the lowest 48.3% of edge-permutation indices are 25% more likely (a modulo bias). The drawn state is "
  f"the inverse of the printed scramble, and that is where DRs come out shorter: inverse best of 3 {nb['best of 3 axes, inverse (linear)']['mean']} against "
  f"{a1['best of 3 axes, inverse (linear)']['mean']} uniform, normal side {nb['best of 3 axes, normal (linear)']['mean']} against {a1['best of 3 axes, normal (linear)']['mean']}. "
  f"The number of twisted corners per axis is also off: chi2 {', '.join(r['chi2'] for r in bad)} on {bad[0]['df']} df, p = "
  f"{', '.join('%.1g' % _p(r['chi2'], r['df']) for r in bad)} (cause not identified). The study therefore draws its own uniform states (`eodrtools mkscr`, written as DR path + exact DR "
  f"finish, inverted; chi2 at most {max(float(r['chi2']) for r in good)} on its 9 tests). `out/checks_scrambles.tsv`; the nissy-scramble results are kept as `out/nissy50k_*`.\n")

# ---------------- A1
w('## A1. Scramble → DR: the shortest DR\n')
w('| | mean | ≤ 8 | ≤ 9 | ≤ 10 | max | sample |')
w('|---|---|---|---|---|---|---|')
for k, r in a1.items():
    w(f"| {k} | {r['mean']} | {P(r['p_le8'])} | {P(r['p_le9'])} | {P(r['p_le10'], 2)} | {r['max']} | {int(r['n']):,} |")
bn, b6, bx = a1['best of 3 axes, normal (linear)'], a1['best of 6 (3 axes x normal/inverse, linear)'], a1['NISS (moves on both sides), best of 3 axes']
w('')
w(f"Answer: one fixed axis is exact (DougCube's 9.5245, max 12). Over the three axes the optimal normal DR averages {bn['mean']} and is ≤ 9 on {P(bn['p_le9'])}; "
  f"best of 6 (adding the inverse) {b6['mean']}, ≤ 9 on {P(b6['p_le9'])}; with NISS {bx['mean']}, ≤ 8 on {P(bx['p_le8'])}, ≤ 9 on {P(bx['p_le9'], 2)}, never above {bx['max']} in the sample.")
c = a1c
w(f"Number of DR solutions on the normal side (all 3 axes): per scramble on average {c['8']['mean_dr_solutions']} of 8 turns, {c['9']['mean_dr_solutions']} of 9 "
  f"(median {c['9']['median']}, none on {P(1 - float(c['9']['p_at_least_one']))}), {c['10']['mean_dr_solutions']} of 10 (median {c['10']['median']}), "
  f"{c['11']['mean_dr_solutions']} of 11, {c['12']['mean_dr_solutions']} of 12; optimal DRs: mean {c['optimal']['mean_dr_solutions']}, median {c['optimal']['median']} "
  f"(a solution and its last turn reversed count as two; {P(c['optimal']['p_at_most_2 (one, up to the last turn\'s direction)'])} have only that pair). `out/a50k_a1_counts.tsv`.\n")
sf = next(x for x in W if 'superflip' in x['finding'])
worst = next(x for x in W if x['question'] == 'A1' and 'worst' in x['finding'])
no10 = next((x for x in W if x['question'] == 'A1' and 'no sub-10' in x['finding']), None)
w('Most striking:')
w(f"- Sub-10 is not universal: {P(1 - float(b6['p_le9']), 1)} of random scrambles have no DR under 10 on any axis, normal or inverse, and {P(1 - float(bx['p_le9']), 2)} have none even with NISS {wid('A1', 'worst')}{' ' + wid('A1', 'no sub-10') if no10 else ''}. The superflip is not special here: {sf['finding']} {wid('A1', 'superflip')}.")
g6 = A['a1']['niss_gain_over_6']
w(f"- NISS beats the best of 6 linear tries on {P(1 - g6['0'] / n)} of scrambles (by 1 on {P(g6['1'] / n)}, by 2 on {P(g6['2'] / n, 2)}); the inverse alone is as good as normal ({a1['best of 3 axes, inverse (linear)']['mean']} vs {bn['mean']}), and taking the better of the two gains {F(float(bn['mean']) - float(b6['mean']), 2)} turns on average.")
w(f"- The fixed-axis row (6.2% ≤ 8, 43% ≤ 9) is what Louis read off nissy's tables; over three axes and both sides ≤ 8 is {P(b6['p_le8'])}, with NISS {P(bx['p_le8'])}.\n")

# ---------------- A2
w('## A2. Optimal DR against the best DR through an EO of ≤ k\n')
w('| EOs used | reference | k | has such an EO | best route = reference | 1 worse | 2 worse | 3+ worse | mean loss (given an EO) |')
w('|---|---|---|---|---|---|---|---|---|')
for kind, short in (('normal EOs', 'normal EOs, DR on normal'), ('normal or inverse', 'normal or inverse EOs, DR on that side'),
                    ('normal, inverse and NISS EOs, NISS', 'normal + inverse + NISS EOs'), ('normal, inverse and NISS EOs, against', 'normal + inverse + NISS EOs')):
    for k in (3, 4, 5, 6):
        r = a2r(a2, kind, k)
        w(f"| {short} | {r['reference']} | {k} | {P(r['p_has_eo'])} | {P(r['p_equals_optimal'])} | {P(r['p_loss1'])} | {P(r['p_loss2'])} | {P(r['p_loss3plus'])} | {r['mean_loss_given_eo']} |")
r5, r4, r6, r3 = (a2r(a2, 'normal EOs', k) for k in (5, 4, 6, 3))
eh = A['estar_hist']
w('')
w(f"Answer: the optimal normal DR (3 axes) goes through an EO of ≤ 3 / 4 / 5 / 6 turns on {P(r3['p_equals_optimal'])} / {P(r4['p_equals_optimal'])} / {P(r5['p_equals_optimal'])} / {P(r6['p_equals_optimal'])} of scrambles; "
  f"the shortest EO inside an optimal DR (E\\*, over all optimal DRs and both EO axes) averages {A['estar_mean']} turns, distribution "
  + ', '.join(f"{k}: {P(v / n)}" for k, v in eh.items() if v) + f". Through EOs of ≤ 5 the best normal route is {r5['mean_best_given_eo']} on average against the optimal {bn['mean']} "
  f"(loss {r5['mean_loss_given_eo']}). Every DR solution starts with an EO, so the optimum never needs EO-breaking turns; among routes through EOs of ≤ 5, a continuation with any turns reaches the optimum where no EO-keeping one does on "
  f"{round(float(r5['p_needs_eo_breaking']) * n)} of {n:,} scrambles; the optimal DR misses short EOs because its EO is long. `out/a50k_a2.tsv`.\n")
w('Most striking:')
w(f"- Restricting to EOs of ≤ 5 (normal) loses the optimal DR on {P(1 - float(r5['p_equals_optimal']))} of scrambles; ≤ 4 on {P(1 - float(r4['p_equals_optimal']))} {wid('A2', 'the best DR through')}.")
w(f"- Typical optimal DRs start with long EOs: E\\* ≥ 6 on {P(sum(v for k, v in eh.items() if int(k) >= 6) / n)}, ≥ 7 on {P(sum(v for k, v in eh.items() if int(k) >= 7) / n)} {wid('A2', 'starts with an EO')}{wid('A2', 'shortest EO inside')}.")
rx5 = a2r(a2, 'normal, inverse and NISS EOs, against', 5)
w(f"- With NISS EOs of ≤ 5 and DR on either side the best route matches or beats the best-of-6 linear optimum on {P(float(rx5['p_equals_optimal']) + float(rx5['p_better_than_optimal_ref']))} of scrambles; against the full NISS optimum it is equal on {P(a2r(a2, 'normal, inverse and NISS EOs, NISS', 5)['p_equals_optimal'])}.\n")

# ---------------- A3
w('## A3. Number of DRs: (EO, DR axis) pairs with EO ≤ k and EO + DR ≤ N\n')
w('| EOs | axes | k | N = 9 | N = 10 | N = 11 | N = 12 | EOs per scramble |')
w('|---|---|---|---|---|---|---|---|')
for eos in ('normal', 'normal + inverse', 'normal + inverse + NISS'):
    for axes in ('one axis (F/B)', 'all three axes'):
        for k in (4, 5):
            rr = [a3r(a3, eos, axes, k, N) for N in (9, 10, 11, 12)]
            w(f"| {eos} | {axes} | {k} | " + ' | '.join(f"{r['mean_pairs']} (none {P(r['p_none'], 0)})" for r in rr) + f" | {rr[0]['mean_eos']} |")
g = A['a3_gains']
w('')
w("Cells: mean number of pairs per scramble (share of scrambles with none). `out/a50k_a3.tsv`.")
y10 = g['normal_N10']; y11 = g['normal_N11']
w(f"Answer: per EO, a ≤ 4-move normal EO yields {F(y10['drs_per_eo_le4'], 3)} (EO, axis) pairs of ≤ 10 and {F(y11['drs_per_eo_le4'], 3)} of ≤ 11; a 5-move EO {F(y10['drs_per_5move_eo'], 3)} and {F(y11['drs_per_5move_eo'], 3)}. "
  f"A scramble has {y10['mean_le4_eos']} normal EOs of ≤ 4 and {y10['mean_5move_eos']} of exactly 5 on average (all axes). ")
gg = g['gain_5_over_4_normal']; gx = g['gain_other_axes_normal_k5']
w(f"Adding the 5-move EOs to the ≤ 4 ones improves the best normal route on {P(gg['p_improves_given_eo_le4'])} of scrambles that have a ≤ 4 EO (mean gain {gg['mean_gain_given_eo_le4']} counting the unimproved, {X['g54_mean_gain_improved']:.2f} among the improved; {P(gg['p_no_eo_le4'])} have no ≤ 4 EO at all). "
  f"Adding the other two EO axes to F/B (EOs ≤ 5) improves it on {P(gx['p_other_axes_better'])} of the {P(gx['p_fixed_axis_has_eo'])} of scrambles that have an F/B EO of ≤ 5 ({gx['mean_fixed_given_eo']} → {gx['mean_all_axes_same_scrambles']}); over all scrambles on {P(X['ax_p_improved_all'])}.\n")
cl = next(r for r in claims if r['entry'] == 'S-DR-261')
w('Most striking:')
w(f"- \"25 four-move EOs or 200 five-move EOs\" (S-DR-261): {cl['ours'].split(' (')[0]}. {cl['verdict'][0].upper() + cl['verdict'][1:]}.")
r10 = a3r(a3, 'normal', 'all three axes', 5, 10); r10x = a3r(a3, 'normal + inverse + NISS', 'all three axes', 5, 10)
w(f"- A DR of ≤ 10 through a normal EO of ≤ 5 is missing on {P(r10['p_none'])} of scrambles; with inverse and NISS EOs on {P(r10x['p_none'])}.")
w(f"- Pairs per EO drop about tenfold from ≤ 4-move to 5-move EOs at N = 10 ({F(y10['drs_per_eo_le4'], 3)} vs {F(y10['drs_per_5move_eo'], 3)}): a 5-move EO is a DR candidate mostly through 5–6 more turns.\n")

# ---------------- B4
w('## B4. Scramble → EO: how many EOs, how short\n')
w('| EOs | axes | ≤ 3 | ≤ 4 (median) | ≤ 5 (median) | ≤ 6 | min ≤ 5 | max ≤ 5 | no EO ≤ 4 |')
w('|---|---|---|---|---|---|---|---|---|')
for eos in ('linear (normal)', 'normal or inverse (linear)', 'NISS (normal, inverse, both)'):
    for axes in ('one axis (F/B)', 'all three axes'):
        r3_, r4_, r5_, r6_ = (b4r(eos, axes, l) for l in (3, 4, 5, 6))
        w(f"| {eos} | {axes} | {r3_['mean_le']} | {r4_['mean_le']} ({r4_['median_le']}) | {r5_['mean_le']} ({r5_['median_le']}) | {r6_['mean_le']} | {r5_['min_le']} | {r5_['max_le']} | {P(r4_['p_none_le'])} |")
w('')
an, al, ab = B['any_axis_niss'], B['any_axis_linear'], B['any_axis_lin_or_inv']
w(f"Means per scramble ({n:,} scrambles; every EO counted, nissy `-a`; nissy's default listing keeps one of each pair of EOs that differ in a last turn's direction, about two fifths in all: `out/default_listing.json`). One axis linear is exact over its 2048 EO states (`out/b4_one_axis_exact.tsv`): ≤ 5 mean {b4x[5]['mean_le']}, at most {b4x[5]['max_le']}; ≤ 4 at most {b4x[4]['max_le']}.")
w(f"Optimal EO over all three axes (1,000,000 states): linear {al['mean']}, normal or inverse {ab['mean']}, NISS {an['mean']}; an EO of ≤ 3 exists on {P(al['p_le3'])} / {P(ab['p_le3'])} / {P(an['p_le3'])} of scrambles, ≤ 2 on {P(al['p_le2'])} / {P(ab['p_le2'])} / {P(an['p_le2'])} (S-EO-85/86).")
gl, gn = A['gap_linear'], A['gap_niss']
w('An N-move EO but no (N+1)-move EO (S-EO-87), all axes, linear: ' + ', '.join(f"N={k.split('_')[0]}: {P(v, 2)}" for k, v in gl.items()) + '; with NISS: ' + ', '.join(f"N={k.split('_')[0]}: {P(v, 2)}" for k, v in gn.items()) + '.\n')
fe = next(x for x in W if x['question'] == 'B4' and 'fewest' in x['finding'])
w('Most striking:')
w(f"- {fe['finding']} {fe['id'] and '[' + fe['id'] + ']'}; the median scramble has {b4r('NISS (normal, inverse, both)', 'all three axes', 5)['median_le']}.")
w(f"- More 3-move than 4-move EOs (S-EO-88): never linearly in {n:,} scrambles ({P(A['more3than4_linear'], 3)}), but it happens with NISS ({P(A['more3than4_niss'], 3)}) {wid('B4', 'more 3-move')}. An N-move EO with no (N+1)-move one occurs only for N = 1, 2 (S-EO-87: JTuu's guess).")
w(f"- With NISS the optimal EO is ≤ 4 on {P(sum(v for k, v in an['hist'].items() if int(k) <= 4) / B['sample_states'], 2)} of scrambles; 6 on {P(an['hist'].get('6', 0) / B['sample_states'], 3)}, 7 never in 1,000,000.\n")

# ---------------- B5
Lb = B['layouts']
w('## B5. Bad-edge layouts\n')
w(f"Exact over all 12!·2^11 edge states (34,650 arrangements of E/M/S pieces x 2048 flip patterns, each standing for 4!^3 permutations): every ordered (F/B, R/L, U/D) triple in `out/b5_layouts.tsv`, sorted triples in `out/b5_sorted.tsv`. "
  f"12/12/12: {Lb['p_all_bad_all_axes_12_12_12']}; some axis already EO'd: {Lb['states_some_axis_eo_solved']}/{Lb['total_arrangement_flip_states']}; all three axes in {{0, 2, 4, 8}}: {Lb['p_all_axes_in_0_2_4_8']}; sorted 4/6/6 {Lb['sorted_6/6/4']}, 6/6/6 {Lb['sorted_6/6/6']}, 6/6/8 {Lb['sorted_6/6/8']}. "
  f"Two axes differ by at most {Lb['max_difference_between_two_axes']}; 12 on one axis leaves at least {Lb['min_other_axes_given_12_on_fb']} on the others; after an EO the other axes have {Lb['other_axes_range_given_0_on_fb']} bad.\n")
w('| bad edges | share of axes | linear ≤ 3 | linear ≤ 4 | linear ≤ 5 | NISS ≤ 3 | NISS ≤ 4 | NISS ≤ 5 | optimal linear EO |')
w('|---|---|---|---|---|---|---|---|---|')
for b in range(0, 13, 2):
    r = byb[b]
    w(f"| {b} | {r['p_state']} | {P(r['p_linear_le3'])} | {P(r['p_linear_le4'])} | {P(r['p_linear_le5'])} | {P(r['p_niss_le3'])} | {P(r['p_niss_le4'])} | {P(r['p_niss_le5'])} | {r['optimal_hist']} |")
w('\nLinear: exact (one axis). NISS: per axis, 1,000,000 random states x 3 axes (12 bad: 1,489 axes, so ±1.8 points). The inverse has the same bad-edge count as the normal side, so "normal or inverse" never helps a 10- or 12-bad axis.\n')
w('Most striking:')
w(f"- 8 bad beats 6 bad for short EOs: linear ≤ 4 {P(byb[8]['p_linear_le4'])} against {P(byb[6]['p_linear_le4'])}, ≤ 3 {P(byb[8]['p_linear_le3'])} against {P(byb[6]['p_linear_le3'])} (S-EO-141: linearly wen is right); with NISS ≤ 4 6 bad is a little better ({P(byb[6]['p_niss_le4'])} vs {P(byb[8]['p_niss_le4'])}).")
w(f"- 12 bad is better than 10 bad with NISS: ≤ 5 on {P(byb[12]['p_niss_le5'])} against {P(byb[10]['p_niss_le5'])}, ≤ 4 on {P(byb[12]['p_niss_le4'])} against {P(byb[10]['p_niss_le4'])}; linearly both are 6–7.")
ten = byb[10]['optimal_hist']
w(f"- No 10-bad axis has a linear EO under 6 (S-EO-24); {ten.split('7:')[1] if '7:' in ten else 0} of the 66 ten-bad states need 7 (S-EO-25/26).\n")

# ---------------- C6/C7
w('## C6 / C7. EO → DR with each option\n')
w('| option | exact/sampled | mean | ≤ 5 | ≤ 6 | ≤ 7 | ≤ 8 | 1 in … for ≤ 6 |')
w('|---|---|---|---|---|---|---|---|')
for r in c7:
    w(f"| {r['option']} | {r['kind']} | {r['mean']} | {P(r['p_le5'], 2)} | {P(r['p_le6'], 2)} | {P(r['p_le7'])} | {P(r['p_le8'])} | {r['one_in_le6']} |")
w('')
w("This is C7's \"typical EO→DR\" table (`out/c7_typical.tsv`); per case (DRM of the first axis) for every option in `out/c6_by_case.tsv`, the joint case of both axes in `out/c6_axis_pairs.tsv`, "
  "normal against inverse in `out/c6_normal_inverse.tsv`. Exact rows: over all 1,082,565 EO-solved cosets (two axes: over corners x E/M-slice places, see README); sampled rows: 10,000,000 states.")
k44 = c6['4c4e']
